// lädt die drei von [recherche] gefundenen Met-CC0-Werke, prüft isPublicDomain nochmals
const fs = require('fs');
const out = process.argv[2];
const API = 'https://collectionapi.metmuseum.org/public/collection/v1';
const werke = [[436319, 'Station 1: Garten-Ebenen (Kaskade im Villengarten)'], [367184, 'Station 1: schlafender Gelehrter (Ausschnitt)'], [340149, 'Papier: Putto neben der Kartenwolke']];
(async () => {
  fs.mkdirSync(out, { recursive: true });
  let csv = 'datei;titel;kuenstler;datum;lizenz;quelle;verwendung\n';
  for (const [id, zweck] of werke) {
    const o = await (await fetch(`${API}/objects/${id}`)).json();
    if (!o.isPublicDomain || !o.primaryImage) { console.log('NICHT CC0', id); continue; }
    fs.writeFileSync(`${out}/met-${id}-roh.jpg`, Buffer.from(await (await fetch(o.primaryImage)).arrayBuffer()));
    csv += [`met-${id}.jpg`, o.title, o.artistDisplayName, o.objectDate, 'CC0 (Met Open Access)', o.objectURL, zweck].map((x) => String(x || '').replace(/;/g, ',')).join(';') + '\n';
    console.log('ok', id, o.title);
  }
  fs.writeFileSync(`${out}/quellen.csv`, csv);
})();

