const { chromium } = require('../../../../../../werkzeuge/node_modules/playwright');
const fs = require('fs');
const path = require('path');

const PRUEFUNG_DIR = __dirname;
const FILM_DIR = path.join(PRUEFUNG_DIR, 'film');
const PROTOKOLL = path.join(PRUEFUNG_DIR, 'protokoll.txt');

let protokoll = [];

async function addProtokolle(browser) {
  const page = await browser.newPage();
  page.on('console', (msg) => {
    if (msg.type() === 'error' || msg.type() === 'warning') {
      protokoll.push(`[${msg.type().toUpperCase()}] ${msg.text()}`);
    }
  });
  page.on('pageerror', (err) => {
    protokoll.push(`[PAGEERROR] ${err.message}`);
  });
  return page;
}

async function test() {
  const browser = await chromium.launch();

  // Test 1: Filmstreifen (1440×900)
  console.log('Test 1: Filmstreifen mit Screenshots...');
  const pageFilm = await addProtokolle(browser);
  await pageFilm.setViewportSize({ width: 1440, height: 900 });
  await pageFilm.goto('http://localhost:8123/marke/entwuerfe/bausteine/demo.html', { waitUntil: 'networkidle' });

  const maxScroll = await pageFilm.evaluate(() => document.documentElement.scrollHeight);
  let filmIndex = 0;
  for (let scrollPos = 0; scrollPos <= maxScroll; scrollPos += 200) {
    await pageFilm.evaluate((y) => window.scrollTo(0, y), scrollPos);
    await pageFilm.waitForTimeout(450);
    const filename = path.join(FILM_DIR, `${String(filmIndex).padStart(3, '0')}.jpg`);
    await pageFilm.screenshot({ path: filename, quality: 60, type: 'jpeg' });
    filmIndex++;
  }
  await pageFilm.close();
  console.log(`  ${filmIndex} Bilder gespeichert`);

  // Test 2: Hover (1440×900)
  console.log('Test 2: Hover auf erste Karte...');
  const pageHover = await addProtokolle(browser);
  await pageHover.setViewportSize({ width: 1440, height: 900 });
  await pageHover.goto('http://localhost:8123/marke/entwuerfe/bausteine/demo.html', { waitUntil: 'networkidle' });

  await pageHover.locator('.b-karte').first().scrollIntoViewIfNeeded();
  await pageHover.hover('.b-karte');
  await pageHover.waitForTimeout(400);
  await pageHover.screenshot({ path: path.join(PRUEFUNG_DIR, 'hover.jpg'), quality: 60, type: 'jpeg' });

  const hoverResult = await pageHover.evaluate(() => {
    const karte = document.querySelector('.b-karte');
    const ergebnis = document.querySelector('.b-karte__ergebnis');
    return {
      istWach: karte?.classList.contains('ist-wach') || false,
      ergebnisOpacity: ergebnis ? window.getComputedStyle(ergebnis).opacity : 'N/A'
    };
  });
  await pageHover.close();
  console.log(`  ist-wach: ${hoverResult.istWach}, ergebnis opacity: ${hoverResult.ergebnisOpacity}`);

  // Test 3: Handy (390×844, isMobile, hasTouch)
  console.log('Test 3: Handy (isMobile, hasTouch)...');
  const pagePhone = await browser.newPage({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true
  });

  pagePhone.on('console', (msg) => {
    if (msg.type() === 'error' || msg.type() === 'warning') {
      protokoll.push(`[PHONE-${msg.type().toUpperCase()}] ${msg.text()}`);
    }
  });
  pagePhone.on('pageerror', (err) => {
    protokoll.push(`[PHONE-PAGEERROR] ${err.message}`);
  });

  await pagePhone.goto('http://localhost:8123/marke/entwuerfe/bausteine/demo.html', { waitUntil: 'networkidle' });

  // Screenshot oben
  await pagePhone.screenshot({ path: path.join(PRUEFUNG_DIR, 'handy-oben.jpg'), quality: 60, type: 'jpeg' });

  // Scroll zur Mitte
  await pagePhone.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight / 2));
  await pagePhone.waitForTimeout(300);
  await pagePhone.screenshot({ path: path.join(PRUEFUNG_DIR, 'handy-mitte.jpg'), quality: 60, type: 'jpeg' });

  // Tippen auf Knopf der ersten Karte
  await pagePhone.evaluate(() => window.scrollTo(0, 0));
  const button = await pagePhone.locator('.b-karte').first();
  await button.tap();
  await pagePhone.waitForTimeout(300);
  await pagePhone.screenshot({ path: path.join(PRUEFUNG_DIR, 'handy-tippen.jpg'), quality: 60, type: 'jpeg' });

  const phoneResult = await pagePhone.evaluate(() => {
    const karte = document.querySelector('.b-karte');
    return karte?.classList.contains('ist-wach') || false;
  });
  console.log(`  Nach Tap - ist-wach: ${phoneResult}`);

  await pagePhone.close();

  // Test 4: reducedMotion (1440×900)
  console.log('Test 4: reducedMotion...');
  const pageQuiet = await browser.newPage({
    reducedMotion: 'reduce'
  });

  pageQuiet.on('console', (msg) => {
    if (msg.type() === 'error' || msg.type() === 'warning') {
      protokoll.push(`[QUIET-${msg.type().toUpperCase()}] ${msg.text()}`);
    }
  });
  pageQuiet.on('pageerror', (err) => {
    protokoll.push(`[QUIET-PAGEERROR] ${err.message}`);
  });

  await pageQuiet.setViewportSize({ width: 1440, height: 900 });
  await pageQuiet.goto('http://localhost:8123/marke/entwuerfe/bausteine/demo.html', { waitUntil: 'networkidle' });

  // Screenshot bei scroll 700
  await pageQuiet.evaluate(() => window.scrollTo(0, 700));
  await pageQuiet.waitForTimeout(300);
  await pageQuiet.screenshot({ path: path.join(PRUEFUNG_DIR, 'ruhig-1.jpg'), quality: 60, type: 'jpeg' });

  // Screenshot bei Kartenreihe (scrollTo Mitte)
  const kartenMitte = await pageQuiet.evaluate(() => {
    const karten = document.querySelector('.b-karten');
    if (!karten) return 0;
    return karten.getBoundingClientRect().top + window.scrollY;
  });
  await pageQuiet.evaluate((y) => window.scrollTo(0, y), kartenMitte);
  await pageQuiet.waitForTimeout(300);
  await pageQuiet.screenshot({ path: path.join(PRUEFUNG_DIR, 'ruhig-2.jpg'), quality: 60, type: 'jpeg' });

  const quietResult = await pageQuiet.evaluate(() => {
    const wort = document.querySelector('.b-auftakt__wort');
    return wort?.style.transform || 'none';
  });
  console.log(`  .b-auftakt__wort transform: ${quietResult}`);

  await pageQuiet.close();

  // Test 5: Wortposition bei Scroll (evaluate)
  console.log('Test 5: Wortposition bei verschiedenen Scroll-Positionen...');
  const pageScroll = await addProtokolle(browser);
  await pageScroll.setViewportSize({ width: 1440, height: 900 });
  await pageScroll.goto('http://localhost:8123/marke/entwuerfe/bausteine/demo.html', { waitUntil: 'networkidle' });

  const scrollPositions = [400, 600];
  const wortData = {};
  for (const scrollY of scrollPositions) {
    await pageScroll.evaluate((y) => window.scrollTo(0, y), scrollY);
    await pageScroll.waitForTimeout(300);

    const rect = await pageScroll.evaluate(() => {
      const wort = document.querySelector('.b-auftakt__wort');
      if (!wort) return null;
      const r = wort.getBoundingClientRect();
      return { top: r.top, left: r.left, scrollY: window.scrollY };
    });
    wortData[scrollY] = rect;
  }

  if (wortData[400] && wortData[600]) {
    const diff = wortData[600].top - wortData[400].top;
    console.log(`  Wortposition Top bei 400px: ${wortData[400].top}`);
    console.log(`  Wortposition Top bei 600px: ${wortData[600].top}`);
    console.log(`  Differenz Top: ${diff} px`);
  }

  await pageScroll.close();

  await browser.close();

  // Protokoll speichern
  if (protokoll.length === 0) {
    protokoll.push('keine');
  }
  fs.writeFileSync(PROTOKOLL, protokoll.join('\n'), 'utf-8');
  console.log(`\nProtokolle: ${protokoll.length} Einträge`);
}

test().catch(console.error);
